function UIActionImpressionFavorabilityDialog:Awake()
    SetButtonAction(self.BtnClose, Bind(self, self.OnBtnBack))
    SetButtonAction(self.BtnLeft, Bind(self, self.OnBtnLeft))
    SetButtonAction(self.BtnRight, Bind(self, self.OnBtnRight))
end

function UIActionImpressionFavorabilityDialog:InitData()
    local t = ActionUtils.GetAllRegionLikabilityLvId(self._mapId)
    self._allLv = checkTable(t) 

    local lv, exp = ActionUtils.GetRegionalPointLikabilityLevel(self._mapId)
    for k, v in pairs(self._allLv) do
        local vo = ActionUtils.GetRegionLikabilityVo(v)
        if checkNumber(vo.level) == lv then
            self._curSelectLevelId = v
            self._curInd = k
        end
    end
end

function UIActionImpressionFavorabilityDialog:FillSelf()
    self:FillRegionnfo()
    self:FillLvInfo()

    CfUtils.SetActive(self.Btnillustrate, false)

    local isMax = ActionUtils.IsMaxLikabilityLevel(self._mapId)
    CfUtils.SetActive(self.TxtprogressNum, not isMax)

    self:RefreshBtns()
end


function UIActionImpressionFavorabilityDialog:FillRegionnfo()
    local vo = ActionUtils.GetRegionPrimaryMapVo(self._mapId)
    if not vo then
        return
    end
    CfUtils.FillText(self.TxtName, vo.name)
    CfUtils.FillImage(self.ImgAreamap, vo.mapIcon)
end

function UIActionImpressionFavorabilityDialog:FillLvInfo()
    local lv, exp = ActionUtils.GetRegionalPointLikabilityLevel(self._mapId)
    CfUtils.FillText(self.TxtLevel, lv)

    local num1, num2 = ActionUtils.GetTaskNumBuyHomeData(self._mapId, lv)
    CfUtils.FillText(self.TxtprogressNum, localize("_num1_<color=#ffffff><size=34>/_num2_", {_num1_ = num1, _num2_ = num2}))

    self:FillAllLv()
end

function UIActionImpressionFavorabilityDialog:OnBtnLeft()
    if self._curInd <= 1 then 
        return
    end

    self._curInd = self._curInd - 1
    self:OnBtnLevel(self._allLv[self._curInd], self._curInd)
    self:RefreshBtns()
end

function UIActionImpressionFavorabilityDialog:OnBtnRight()
    if self._curInd >= table.count(self._allLv) then 
        return
    end
    self._curInd = self._curInd + 1

    self:OnBtnLevel(self._allLv[self._curInd], self._curInd)
    self:RefreshBtns()
end

function UIActionImpressionFavorabilityDialog:RefreshBtns()
    CfUtils.SetActive(self.BtnLeft,  checkNumber(self._curInd) > 1)
    CfUtils.SetActive(self.BtnRight,  checkNumber(self._curInd) < table.count(self._allLv))
end

function UIActionImpressionFavorabilityDialog:FillAllLv()
    local lv, exp = ActionUtils.GetRegionalPointLikabilityLevel(self._mapId)

    local childGo = self.ButtonItem.transform:Find("BtnPage")
    CfUtils.SetActive(childGo, false)
    for k, id in pairs(self._allLv) do
        if checkNumber(self._curSelectLevelId) <= 0 then
            self._curSelectLevelId = id
            self._curInd = k
        end
        
        local likeVo = ActionUtils.GetRegionLikabilityVo(id)
        local go = self.ButtonItem.transform:Find("BtnPage"..(k - 1))
        if not go then
            go = CfUtils.InstantiateGo(childGo, self.ButtonItem)
            go.name = "BtnPage"..(k - 1)
        end
        if go then
            CfUtils.SetActive(go, true)
            local isSelect = (id == self._curSelectLevelId)
            CfUtils.SetActive(go.transform:Find("Select"), isSelect)
            CfUtils.FillText(go.transform:Find("Normal/TxtNumber"), likeVo.level)

            local isUnlock = (lv >= checkNumber(likeVo.level))
            CfUtils.SetActive(go.transform:Find("Lock"), not isUnlock)
            CfUtils.SetUISwitchText(go.transform:Find("Normal/TxtNumber"), isUnlock and 1 or 2)
            CfUtils.SetUISwitchText(go.transform:Find("Normal/TxtLv"), isUnlock and 1 or 2)
            CfUtils.SetUISwitchImage(go.transform:Find("Normal/Imgbg"), isUnlock and 1 or 2)

            SetButtonAction(go, function()
                self:OnBtnLevel(id, k)
            end)

            CfUtils.PlayAnimation(go.transform:Find("Normal"), isSelect and "ActionImpressionFavorabilityDialog_BtnPage_SelectNumber" or "ActionImpressionFavorabilityDialog_BtnPage_NormalNumber")
        end
    end

    self:FillRewards()
end

function UIActionImpressionFavorabilityDialog:OnBtnLevel(id, ind)
    self._curInd = ind
    local lv, exp = ActionUtils.GetRegionalPointLikabilityLevel(self._mapId)

    local ind = checkNumber(table.getKey(self._allLv, checkString(self._curSelectLevelId)))
    local vo = ActionUtils.GetRegionLikabilityVo(self._curSelectLevelId)

    local go = self.ButtonItem.transform:Find("BtnPage"..ind - 1)
    if go then
        local isUnlock = (lv >= checkNumber(vo.level))
        CfUtils.SetActive(go.transform:Find("Select"), false)
        CfUtils.SetUISwitchText(go.transform:Find("Normal/TxtNumber"), isUnlock and 1 or 2)
        CfUtils.SetUISwitchText(go.transform:Find("Normal/TxtLv"), isUnlock and 1 or 2)

        CfUtils.PlayAnimation(go.transform:Find("Normal"), "ActionImpressionFavorabilityDialog_BtnPage_NormalNumber")
    end
    
    self._curSelectLevelId = checkNumber(id)
    local ind = checkNumber(table.getKey(self._allLv, checkString(self._curSelectLevelId)))
    vo = ActionUtils.GetRegionLikabilityVo(self._curSelectLevelId)

    go = self.ButtonItem.transform:Find("BtnPage"..ind - 1)
    if go then
        local isUnlock = (lv >= checkNumber(vo.level))
        CfUtils.SetActive(go.transform:Find("Select"), true)
        CfUtils.SetUISwitchText(go.transform:Find("Normal/TxtNumber"), isUnlock and 1 or 2)
        CfUtils.SetUISwitchText(go.transform:Find("Normal/TxtLv"), isUnlock and 1 or 2)

        CfUtils.PlayAnimation(go.transform:Find("Normal"), "ActionImpressionFavorabilityDialog_BtnPage_SelectNumber")
    end

    self:FillRewards()
    self:RefreshBtns()
end

function UIActionImpressionFavorabilityDialog:FillRewards()
    local vo = ActionUtils.GetRegionLikabilityVo(self._curSelectLevelId)
    if not vo then
        return
    end
    local t = ActionUtils.GetAllShowReward(vo.levelUpExplain)
    for i = 1, 3 do
        local go = self["Cell"..i]
        local data = t[checkString(i)]

        self:FillReward(go, data, checkString(i))
    end
end

function UIActionImpressionFavorabilityDialog:FillReward(go, data, type)
    if not go then
        return
    end
    local cellRootGo = go.transform:Find("CellRoot")
    local scrollViewGo = cellRootGo.transform:Find("ScrollView")
    local emptyNodeGo = cellRootGo.transform:Find("EmptyNode")

    if not data then
        CfUtils.SetActive(scrollViewGo, false)
        CfUtils.SetActive(emptyNodeGo, true)
        return
    else
        CfUtils.SetActive(scrollViewGo, true)
        CfUtils.SetActive(emptyNodeGo, false)
    end

    if checkNumber(type) == 1 then
        self:FillQuest(scrollViewGo, data, type)
    elseif checkNumber(type) == 2 then
        self:FillStore(scrollViewGo, data, type)
    elseif checkNumber(type) == 3 then
        self:FillSalout(scrollViewGo, data, type)
    end
end

function UIActionImpressionFavorabilityDialog:FillQuest(go, data, type)
    if not go or not data then
        return
    end
    local lv, exp = ActionUtils.GetRegionalPointLikabilityLevel(self._mapId)
    local vo = ActionUtils.GetRegionLikabilityVo(self._curSelectLevelId)
    local isUnlock = (lv >= checkNumber(vo.level))

    local parGo = go.transform:Find("Content")
    local childGo = parGo.transform:Find("Item1")

    local t = {}
    for k, v in pairs(data) do
        print(v.parameter)
        local vo = QuestConfMgr:GetInstance():GetQuestVoById(v.parameter)
        if not t[checkString(vo.pointID)] then
            t[checkString(vo.pointID)] = {}
        end
        table.insert(t[checkString(vo.pointID)], vo)
    end

    for i = 1, parGo.childCount do 
        local go = parGo.transform:GetChild(i - 1)
        CfUtils.SetActive(go, false)
    end

    for k, v in pairs(t) do
        local cellGo = parGo.transform:Find("go"..k)
        if not cellGo then
            cellGo = CfUtils.InstantiateGo(childGo, parGo)
            cellGo.name = "go"..k
        end
        CfUtils.SetActive(cellGo, true)

        local vo = ActionUtils.GetRegionSecondaryMapVo(v[1].pointID)
        CfUtils.FillText(cellGo.transform:Find("TxtName"), vo.name)
        local str = ""
        for _, vo in pairs(v) do
            if _ > 1 then
                str = str.."\n"
            end

            if checkNumber(vo.levelType) == 2 then
                local foodType = FoodType[checkNumber(vo.foodType)] or localize("食材")
                str = str..localize("解锁[_num_副本]难度", {_num_ = foodType})
            else
                str = str..localize("解锁难度")
            end
            str = str..vo.label
        end
        CfUtils.FillText(cellGo.transform:Find("TxtDesc"), str)
        CfUtils.SetUISwitchImage(cellGo.transform:Find("TxtName/ImgLock"), isUnlock and 2 or 1)
    end
end

function UIActionImpressionFavorabilityDialog:FillStore(go, data, type)
    if not go or not data then
        return
    end
    local lv, exp = ActionUtils.GetRegionalPointLikabilityLevel(self._mapId)
    local vo = ActionUtils.GetRegionLikabilityVo(self._curSelectLevelId)
    local isUnlock = (lv >= checkNumber(vo.level))

    local parGo = go.transform:Find("Content")
    local child1Go = parGo.transform:Find("Item1")
    local child2Go = parGo.transform:Find("Item2")

    local vo = ActionUtils.GetRegionLikabilityRewardTypeVo(type)
    CfUtils.FillText(child1Go.transform:Find("TxtName"), vo.title)

    for i = 1, parGo.childCount do 
        local cellGo = parGo.transform:GetChild(i - 1)
        CfUtils.SetActive(cellGo, false)
    end

    CfUtils.SetActive(child1Go, true)
    for k, v in pairs(data) do
        local cellGo = parGo.transform:Find("go"..k)
        if not cellGo then
            cellGo = CfUtils.InstantiateGo(child2Go, parGo)
            cellGo.name = "go"..k
        end
        CfUtils.SetActive(cellGo, true)

        local str = ""
        if checkNumber(v.unlockType2) == 1 then
            str = str..localize("解锁材料")
        else
            str = str..localize("解锁食材")
        end
        local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(v.parameter)
        str = str.."["..vo.name.."]"
        CfUtils.RefeshGoodGo2(cellGo.transform:Find("GoodNode"), vo.id, nil, nil, nil, function()
            GameUtils.ShowCommonTipsBoard(cellGo.transform:Find("GoodNode"), vo.name, vo.desc, vo.quality, vo.id)
        end)

        CfUtils.FillText(cellGo.transform:Find("TxtDesc"), str)
        CfUtils.SetUISwitchImage(cellGo.transform:Find("ImgLock"), isUnlock and 2 or 1)
    end
end

function UIActionImpressionFavorabilityDialog:FillSalout(go, data, type)
    if not go or not data then
        return
    end

    local lv, exp = ActionUtils.GetRegionalPointLikabilityLevel(self._mapId)
    local vo = ActionUtils.GetRegionLikabilityVo(self._curSelectLevelId)
    local isUnlock = (lv >= checkNumber(vo.level))

    local parGo = go.transform:Find("Content")
    local child1Go = parGo.transform:Find("Item1")
    local child2Go = parGo.transform:Find("Item2")

    local vo = ActionUtils.GetRegionLikabilityRewardTypeVo(type)
    CfUtils.FillText(child1Go.transform:Find("TxtName"), vo.title)
    CfUtils.FillText(child2Go.transform:Find("TxtName"), vo.title)

    --只会有一个
    vo = GoodsConfMgr:GetInstance():GetGoodsVoById(data[1].parameter)
    if not vo then
        CfUtils.SetActive(child2Go, false)
    else
        CfUtils.SetActive(child2Go, true)
        CfUtils.RefeshGoodGo2(child2Go.transform:Find("Group/GoodNode"), vo.id, nil, nil, nil, function()
            local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(vo.id)
            GameUtils.ShowCommonTipsBoard(child2Go.transform:Find("Group/GoodNode"), goodsVo.name, goodsVo.desc, goodsVo.quality, goodsVo.id)
        end)

        CfUtils.FillText(child2Go.transform:Find("Group/TxtDesc"), localize("订单中有机会获得[_name_]",{_name_ = vo.name}))
        CfUtils.SetUISwitchImage(child2Go.transform:Find("Group/ImgLock"), isUnlock and 2 or 1)
    end
    
    parGo = child1Go
    local childGo = parGo.transform:Find("TxtDesc")

    local t = {}
    for k, v in pairs(data) do
        local _t = CfUtils.Split(v.describe)
        for _, str in pairs(_t) do
            table.insert(t, str)
        end
    end

    for k, v in pairs(t) do
        local cellGo = parGo.transform:Find("go"..k)
        if not cellGo then
            cellGo = CfUtils.InstantiateGo(childGo, parGo)
            cellGo.name = "go"..k
        end
        CfUtils.SetActive(cellGo, true)
        CfUtils.FillText(cellGo, v)
        CfUtils.SetUISwitchImage(cellGo.transform:Find("ImgLock"), isUnlock and 2 or 1)
    end

    if table.count(t) < parGo.childCount - 2 then
        for i = table.count(t) + 1, parGo.childCount - 2 do
            local cellGo = parGo.transform:Find("go"..i)
            CfUtils.SetActive(cellGo, false)
        end
    end
end

