function UIActionImpressionFavorabilityDialog:OnInitialize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        local argument = self.controller.Argument.parameters
        if not argument then
            return
        end
        self._mapId = checkNumber(argument.mapId)  

        self:InitData()
        self:FillSelf()
    end))
    return coWait
end

function UIActionImpressionFavorabilityDialog:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end))
    return coWait
end

return UIActionImpressionFavorabilityDialog
